import os
import threading
from queue import Queue, Empty
from typing import Callable, Iterable, Iterator, Optional, Union

from deepgram import DeepgramClient, DeepgramClientOptions, LiveOptions, LiveTranscriptionEvents


class DeepgramStreamingRecognizer:
    def __init__(
        self,
        api_key: Optional[str] = None,
        model: str = "nova-2",
        language: str = "en-US",
    ) -> None:
        api_key = api_key or os.environ.get("DEEPGRAM_API_KEY")
        if not api_key:
            raise ValueError("DEEPGRAM_API_KEY is required")

        self._client = DeepgramClient(
            api_key=api_key,
            config=DeepgramClientOptions(options={"keepalive": "true"}),
        )
        self._model = model
        self._language = language

    def stream_transcribe(
        self,
        audio_chunks: Iterable[bytes],
        on_partial: Optional[Callable[[str], None]] = None,
        on_final: Optional[Callable[[str], None]] = None,
        encoding: str = "linear16",
        sample_rate: int = 16000,
        channels: int = 1,
    ) -> Iterator[dict]:
        """
        Consume an iterable of raw audio chunks and yield streaming recognition events.

        Yields dict events:
          - {"type": "partial", "text": "...", "is_final": False}
          - {"type": "final", "text": "...", "is_final": True}
        """

        events: "Queue[dict]" = Queue()
        done = threading.Event()

        def _emit_partial(text: str) -> None:
            if text:
                event = {"type": "partial", "text": text, "is_final": False}
                events.put(event)
                if on_partial:
                    on_partial(text)

        def _emit_final(text: str) -> None:
            if text:
                event = {"type": "final", "text": text, "is_final": True}
                events.put(event)
                if on_final:
                    on_final(text)

        live = self._client.listen.websocket.v("1")

        def on_open(_: object, __: object) -> None:
            pass

        def on_message(_: object, result: object, **kwargs: object) -> None:
            try:
                alt = result.channel.alternatives[0]
                transcript = getattr(alt, "transcript", "") or ""
                is_final = bool(getattr(result, "is_final", False))
                speech_final = bool(getattr(result, "speech_final", False))

                if transcript:
                    if is_final or speech_final:
                        _emit_final(transcript)
                    else:
                        _emit_partial(transcript)
            except Exception:
                return

        def on_close(_: object, __: object, **kwargs: object) -> None:
            done.set()

        def on_error(_: object, error: object, **kwargs: object) -> None:
            done.set()
            raise RuntimeError(f"Deepgram streaming error: {error}")

        live.on(LiveTranscriptionEvents.Open, on_open)
        live.on(LiveTranscriptionEvents.Transcript, on_message)
        live.on(LiveTranscriptionEvents.Close, on_close)
        live.on(LiveTranscriptionEvents.Error, on_error)

        options = LiveOptions(
            model=self._model,
            language=self._language,
            encoding=encoding,
            sample_rate=sample_rate,
            channels=channels,
            interim_results=True,
            punctuate=True,
            smart_format=True,
            vad_events=True,
        )

        if not live.start(options):
            raise RuntimeError("Failed to start Deepgram websocket")

        try:
            for chunk in audio_chunks:
                if not chunk:
                    continue
                live.send(chunk)
                while True:
                    try:
                        event = events.get_nowait()
                        yield event
                    except Empty:
                        break
            live.finish()
        finally:
            done.wait(timeout=5)
            live.close()

        while True:
            try:
                yield events.get_nowait()
            except Empty:
                break


def transcribe_stream(
    audio_chunks: Iterable[bytes],
    api_key: Optional[str] = None,
    model: str = "nova-2",
    language: str = "en-US",
) -> Iterator[dict]:
    recognizer = DeepgramStreamingRecognizer(api_key=api_key, model=model, language=language)
    return recognizer.stream_transcribe(audio_chunks)
